n = int(input())

carp = [["#"]]
for k in range(1, n + 1):
    tmp = []
    for _ in range(3):
        for c in carp[k - 1]:
            tmp.append(c * 3)

    tmp = list(map(list, tmp))

    cen = 3**(k - 1)
    for i in range(3**k):
        for j in range(3**k):
            if cen <= i < cen + 3**(k - 1) and cen <= j < cen + 3**(k - 1):
                tmp[i][j] = "."
    carp.append(tmp)

for c in carp[n]:
    print("".join(c))
